// src/routes/onboarding.ts
init_db();
var onboardingRouter = new Hono2;
onboardingRouter.post("/", async (c) => {
  const user = c.get("user");
  if (!user) {
    return c.json({ error: "Unauthorized" }, 401);
  }
  const existingMembership = await db4.membership.findUnique({
    where: { userId: user.id }
  });
  if (existingMembership) {
    return c.json({ error: "User already belongs to an organization" }, 400);
  }
  const body = await c.req.json();
  const parsed = createOrganizationRequestSchema.safeParse(body);
  if (!parsed.success) {
    return c.json({ error: "Invalid request", details: parsed.error.issues }, 400);
  }
  const { organizationName, locationName, locationAddress } = parsed.data;
  const result = await db4.$transaction(async (tx) => {
    const organization = await tx.organization.create({
      data: { name: organizationName }
    });
    const location = await tx.location.create({
      data: {
        name: locationName,
        address: locationAddress ?? null,
        organizationId: organization.id
      }
    });
    const membership = await tx.membership.create({
      data: {
        userId: user.id,
        organizationId: organization.id,
        role: "OWNER",
        locationId: null
      }
    });
    return { organization, location, membership };
  });
  return c.json({
    organization: {
      id: result.organization.id,
      name: result.organization.name,
      createdAt: result.organization.createdAt.toISOString(),
      updatedAt: result.organization.updatedAt.toISOString()
    },
    location: {
      id: result.location.id,
      name: result.location.name,
      address: result.location.address,
      organizationId: result.location.organizationId,
      createdAt: result.location.createdAt.toISOString(),
      updatedAt: result.location.updatedAt.toISOString()
    },
    membership: {
      id: result.membership.id,
      userId: result.membership.userId,
      organizationId: result.membership.organizationId,
      role: result.membership.role,
      locationId: result.membership.locationId,
      createdAt: result.membership.createdAt.toISOString(),
      updatedAt: result.membership.updatedAt.toISOString()
    }
  });
});

// src/routes/locations.ts
init_db();
init_subscription();
var locationsRouter = new Hono2;
var requireOwner = async (c) => {
  const user = c.get("user");
  if (!user)
    return null;
  const membership = await db4.membership.findUnique({
    where: { userId: user.id }
  });
  if (!membership || membership.role !== "OWNER")
    return null;
  return membership;
};
var checkLocationLimit = async (organizationId, c) => {
  const subscription = await getOrganizationSubscription(organizationId);
  if (!subscription || !subscription.isActive) {
    return {
      allowed: false,
      error: "subscription_inactive",
      message: "Tu suscripci\xF3n no est\xE1 activa"
    };
  }
  const tierLimits = SUBSCRIPTION_TIERS[subscription.tier]?.limits;
  const maxLocations = tierLimits?.locations ?? -1;
  if (maxLocations === -1) {
    return { allowed: true };
  }
  const currentCount = await db4.location.count({ where: { organizationId } });
  if (currentCount >= maxLocations) {
    return {
      allowed: false,
      error: "limit_exceeded",
      message: `Has alcanzado el l\xEDmite de ${maxLocations} ubicaciones. Actualiza tu plan para m\xE1s.`,
      upgradeUrl: "/subscription",
      current: currentCount,
      limit: maxLocations
    };
  }
  return { allowed: true, current: currentCount, limit: maxLocations };
};
locationsRouter.get("/", async (c) => {
  const user = c.get("user");
  if (!user)
    return c.json({ error: "Unauthorized" }, 401);
  const membership = await db4.membership.findUnique({
    where: { userId: user.id }
  });
  if (!membership)
    return c.json({ error: "No organization" }, 403);
  const locations = await db4.location.findMany({
    where: {
      organizationId: membership.organizationId,
      ...membership.role === "MANAGER" && membership.locationId ? { id: membership.locationId } : {}
    },
    orderBy: { name: "asc" }
  });
  return c.json({
    locations: locations.map((loc) => ({
      id: loc.id,
      name: loc.name,
      address: loc.address,
      organizationId: loc.organizationId,
      createdAt: loc.createdAt.toISOString(),
      updatedAt: loc.updatedAt.toISOString()
    }))
  });
});
locationsRouter.post("/", async (c) => {
  const membership = await requireOwner(c);
  if (!membership)
    return c.json({ error: "Owner access required" }, 403);
  const limitCheck = await checkLocationLimit(membership.organizationId, c);
  if (!limitCheck.allowed) {
    return c.json({
      error: limitCheck.error,
      message: limitCheck.message,
      upgradeUrl: limitCheck.upgradeUrl,
      current: limitCheck.current,
      limit: limitCheck.limit
    }, 403);
  }
  const body = await c.req.json();
  const parsed = createLocationRequestSchema.safeParse(body);
  if (!parsed.success) {
    return c.json({ error: "Invalid request", details: parsed.error.issues }, 400);
  }
  const location = await db4.location.create({
    data: {
      name: parsed.data.name,
      address: parsed.data.address ?? null,
      organizationId: membership.organizationId
    }
  });
  return c.json({
    id: location.id,
    name: location.name,
    address: location.address,
    organizationId: location.organizationId,
    createdAt: location.createdAt.toISOString(),
    updatedAt: location.updatedAt.toISOString()
  });
});

