productsRouter.put("/:id", async (c) => {
  const membership = await requireOwner2(c);
  if (!membership)
    return c.json({ error: "Owner access required" }, 403);
  const productId = c.req.param("id");
  const body = await c.req.json();
  const parsed = updateProductRequestSchema.safeParse(body);
  if (!parsed.success) {
    return c.json({ error: "Invalid request", details: parsed.error.issues }, 400);
  }
  const existing = await db4.product.findFirst({
    where: {
      id: productId,
      organizationId: membership.organizationId
    }
  });
  if (!existing) {
    return c.json({ error: "Product not found" }, 404);
  }
  const product = await db4.product.update({
    where: { id: productId },
    data: {
      ...parsed.data.name !== undefined && { name: parsed.data.name },
      ...parsed.data.sku !== undefined && { sku: parsed.data.sku },
      ...parsed.data.unit !== undefined && { unit: parsed.data.unit },
      ...parsed.data.category !== undefined && { category: parsed.data.category },
      ...parsed.data.isActive !== undefined && { isActive: parsed.data.isActive }
    }
  });
  return c.json({
    id: product.id,
    name: product.name,
    sku: product.sku,
    unit: product.unit,
    category: product.category,
    organizationId: product.organizationId,
    isActive: product.isActive,
    createdAt: product.createdAt.toISOString(),
    updatedAt: product.updatedAt.toISOString()
  });
});
productsRouter.delete("/:id", async (c) => {
  const membership = await requireOwner2(c);
  if (!membership)
    return c.json({ error: "Owner access required" }, 403);
  const productId = c.req.param("id");
  const existing = await db4.product.findFirst({
    where: {
      id: productId,
      organizationId: membership.organizationId
    }
  });
  if (!existing) {
    return c.json({ error: "Product not found" }, 404);
  }
  await db4.product.update({
    where: { id: productId },
    data: { isActive: false }
  });
  return c.json({ success: true });
});

