ordersRouter.post("/", async (c) => {
  const membership = await requireOwner5(c);
  if (!membership)
    return c.json({ error: "Owner access required" }, 403);
  const body = await c.req.json();
  const parsed = createOrderRequestSchema.safeParse(body);
  if (!parsed.success) {
    return c.json({ error: "Invalid request", details: parsed.error.issues }, 400);
  }
  const { locationId, supplierId, items, notes, sendImmediately } = parsed.data;
  const [location, supplier] = await Promise.all([
    db4.location.findFirst({
      where: { id: locationId, organizationId: membership.organizationId }
    }),
    db4.supplier.findFirst({
      where: { id: supplierId, organizationId: membership.organizationId }
    })
  ]);
  if (!location)
    return c.json({ error: "Location not found" }, 404);
  if (!supplier)
    return c.json({ error: "Supplier not found" }, 404);
  const totalAmount = items.reduce((sum, item) => sum + item.quantity * (item.unitPrice ?? 0), 0);
  const order = await db4.purchaseOrder.create({
    data: {
      orderNumber: generateOrderNumber(),
      locationId,
      supplierId,
      status: sendImmediately ? "SENT" : "DRAFT",
      totalAmount: totalAmount > 0 ? totalAmount : null,
      notes: notes ?? null,
      sentAt: sendImmediately ? new Date : null,
      items: {
        create: items.map((item) => ({
          productId: item.productId,
          quantity: item.quantity,
          unitPrice: item.unitPrice ?? null
        }))
      }
    },
    include: {
      items: {
        include: { product: { select: { id: true, name: true, unit: true } } }
      },
      supplier: { select: { id: true, name: true } },
      location: { select: { id: true, name: true } }
    }
  });
  await incrementOrderCount(membership.organizationId);
  return c.json(formatOrder(order));
});
ordersRouter.put("/:id/send", async (c) => {
  const membership = await requireOwner5(c);
  if (!membership)
    return c.json({ error: "Owner access required" }, 403);
  const orderId = c.req.param("id");
  const existing = await db4.purchaseOrder.findFirst({
    where: {
      id: orderId,
      location: { organizationId: membership.organizationId },
      status: "DRAFT"
    }
  });
  if (!existing)
    return c.json({ error: "Order not found or already sent" }, 404);
  const order = await db4.purchaseOrder.update({
    where: { id: orderId },
    data: {
      status: "SENT",
      sentAt: new Date
    },
    include: {
      items: {
        include: { product: { select: { id: true, name: true, unit: true } } }
      },
      supplier: { select: { id: true, name: true } },
      location: { select: { id: true, name: true } }
    }
  });
  return c.json({ order: formatOrder(order) });
});
ordersRouter.put("/:id/confirm", async (c) => {
  const user = c.get("user");
  const membership = await getMembership4(c);
  if (!membership || !user)
    return c.json({ error: "Unauthorized" }, 401);
  const orderId = c.req.param("id");
  const body = await c.req.json();
  const parsed = confirmDeliveryRequestSchema.safeParse(body);
  if (!parsed.success) {
    return c.json({ error: "Invalid request", details: parsed.error.issues }, 400);
  }
  const existing = await db4.purchaseOrder.findFirst({
    where: {
      id: orderId,
      location: { organizationId: membership.organizationId },
      status: "SENT",
      ...membership.role === "MANAGER" && membership.locationId ? { locationId: membership.locationId } : {}
    },
    include: { items: true }
  });
  if (!existing)
    return c.json({ error: "Order not found or not sent" }, 404);
  const { delivered, notes, photoUrl } = parsed.data;
  const order = await db4.purchaseOrder.update({
    where: { id: orderId },
    data: {
      status: delivered ? "DELIVERED" : "NOT_DELIVERED",
      deliveredAt: delivered ? new Date : null,
      confirmedById: user.id,
      confirmPhoto: photoUrl ?? null,
      notes: notes ? existing.notes ? `${existing.notes}

${notes}` : notes : existing.notes
    },
    include: {
      items: {
        include: { product: { select: { id: true, name: true, unit: true } } }
      },
      supplier: { select: { id: true, name: true } },
      location: { select: { id: true, name: true } }
    }
  });
  if (delivered) {
    for (const item of existing.items) {
      await db4.stockLevel.upsert({
        where: {
          productId_locationId: {
            productId: item.productId,
            locationId: existing.locationId
          }
        },
        update: {
          onHand: { increment: item.quantity }
        },
        create: {
          productId: item.productId,
          locationId: existing.locationId,
          onHand: item.quantity,
          dailyUsage: 0
        }
      });
    }
  }
  if (!delivered) {
    await db4.alert.create({
      data: {
        type: "DELIVERY_FAILED",
        severity: "CRIT",
        title: `Delivery Failed: ${order.orderNumber}`,
        message: `Order ${order.orderNumber} was not delivered. ${notes ?? ""}`,
        organizationId: membership.organizationId,
        locationId: existing.locationId,
        relatedId: orderId,
        relatedType: "purchase_order"
      }
    });
  }
  return c.json(formatOrder(order));
});

