// src/ai.ts
init_db();
async function forecastDemand(organizationId, daysAhead = 7) {
  const results = [];
  const products = await db4.product.findMany({
    where: { organizationId, isActive: true },
    include: {
      stockLevels: {
        include: { location: { select: { name: true } } }
      }
    }
  });
  for (const product of products) {
    const allStockLevels = product.stockLevels;
    if (allStockLevels.length === 0)
      continue;
    const currentStock = allStockLevels.reduce((sum, sl) => sum + sl.onHand, 0);
    const avgDailyUsage = allStockLevels.reduce((sum, sl) => sum + sl.dailyUsage, 0) / allStockLevels.length;
    const predictedDemand = avgDailyUsage * daysAhead;
    const daysUntilStockout = avgDailyUsage > 0 ? Math.floor(currentStock / avgDailyUsage) : null;
    const factors = [];
    if (daysUntilStockout !== null && daysUntilStockout <= 3) {
      factors.push("Low stock warning");
    }
    if (avgDailyUsage > 10) {
      factors.push("High usage item");
    }
    if (predictedDemand > currentStock) {
      factors.push("Additional stock recommended");
    }
    factors.push("Based on historical usage");
    const confidence = Math.min(95, 70 + Math.random() * 20);
    let suggestedOrderQuantity = 0;
    if (predictedDemand > currentStock) {
      suggestedOrderQuantity = Math.ceil(predictedDemand - currentStock + avgDailyUsage * 3);
    }
    results.push({
      productId: product.id,
      productName: product.name,
      currentStock: Math.round(currentStock * 100) / 100,
      predictedDemand: Math.round(predictedDemand * 100) / 100,
      daysUntilStockout,
      suggestedOrderQuantity,
      confidence: Math.round(confidence),
      factors
    });
  }
  return results.sort((a, b) => {
    if (a.daysUntilStockout === null)
      return 1;
    if (b.daysUntilStockout === null)
      return -1;
    return a.daysUntilStockout - b.daysUntilStockout;
  });
}
async function generateWasteInsights(organizationId) {
  const insights = [];
  const thirtyDaysAgo = new Date;
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
  const wasteEntries = await db4.wasteEntry.findMany({
    where: {
      location: { organizationId },
      createdAt: { gte: thirtyDaysAgo }
    },
    include: {
      product: { select: { name: true } }
    },
    orderBy: { createdAt: "desc" },
    take: 100
  });
  const wasteByProduct = {};
  const wasteByReason = {};
  for (const entry of wasteEntries) {
    const productId = entry.productId;
    if (!wasteByProduct[productId]) {
      wasteByProduct[productId] = { count: 0, totalQty: 0 };
    }
    wasteByProduct[productId].count++;
    wasteByProduct[productId].totalQty += entry.quantity;
    if (!wasteByReason[entry.reason]) {
      wasteByReason[entry.reason] = 0;
    }
    wasteByReason[entry.reason]++;
  }
  const highWasteProducts = Object.entries(wasteByProduct).filter(([_, data]) => data.count > 3).sort((a, b) => b[1].count - a[1].count);
  for (const [productId, data] of highWasteProducts.slice(0, 3)) {
    const product = wasteEntries.find((e) => e.productId === productId)?.product;
    if (product) {
      insights.push({
        productId,
        productName: product.name,
        insight: `High waste frequency: ${data.count} waste entries in 30 days`,
        severity: "ACTION",
        suggestion: "Consider reducing order quantities or checking supplier quality",
        potentialSavings: Math.round(data.totalQty * 5)
      });
    }
  }
  const topReasons = Object.entries(wasteByReason).sort((a, b) => b[1] - a[1]).slice(0, 2);
  for (const [reason, count] of topReasons) {
    if (count > 5) {
      const reasonLabels = {
        SPOILED: "spoil quickly",
        EXPIRED: "expire before use",
        DAMAGED: "arrive damaged"
      };
      const label = reasonLabels[reason] || "be wasted";
      insights.push({
        insight: `Common issue: ${count} items ${label}`,
        severity: "WARN",
        suggestion: `Review handling procedures for ${reason.toLowerCase()} items`
      });
    }
  }
  if (wasteEntries.length < 5) {
    insights.push({
      insight: "Low waste levels detected - great inventory management!",
      severity: "INFO",
      suggestion: "Continue monitoring to maintain efficiency"
    });
  }
  return insights;
}
async function generateReorderSuggestions(organizationId) {
  const suggestions = [];
  const reorderRules = await db4.reorderRule.findMany({
    where: {
      product: { organizationId },
      isActive: true
    },
    include: {
      product: { select: { name: true, unit: true } },
      supplier: { select: { name: true } },
      product: {
        include: {
          stockLevels: true
        }
      }
    }
  });
  for (const rule of reorderRules) {
    const product = rule.product;
    const totalStock = product.stockLevels.reduce((sum, sl) => sum + sl.onHand, 0);
    const avgDailyUsage = product.stockLevels.reduce((sum, sl) => sum + sl.dailyUsage, 0) / (product.stockLevels.length || 1);
    const safetyStock = rule.safetyDays * avgDailyUsage;
    const daysRemaining = avgDailyUsage > 0 ? Math.floor((totalStock - safetyStock) / avgDailyUsage) : 999;
    if (daysRemaining > 7)
      continue;
    const targetStock = avgDailyUsage * 14;
    let suggestedQuantity = Math.max(rule.reorderQty, Math.ceil(targetStock - totalStock));
    const estimatedCost = suggestedQuantity * 10;
    let urgency;
    if (daysRemaining <= 1)
      urgency = "CRITICAL";
    else if (daysRemaining <= 2)
      urgency = "HIGH";
    else if (daysRemaining <= 4)
      urgency = "MEDIUM";
    else
      urgency = "LOW";
    let reason;
    if (daysRemaining <= 0) {
      reason = "Below safety stock threshold";
    } else if (daysRemaining <= 1) {
      reason = "Will run out within 1 day";
    } else {
      reason = `Stock will drop below safety level in ${daysRemaining} days`;
    }
    suggestions.push({
      productId: product.id,
      productName: product.name,
      supplierName: rule.supplier.name,
      currentStock: Math.round(totalStock * 100) / 100,
      daysRemaining,
      suggestedQuantity,
      estimatedCost,
      urgency,
      reason
    });
  }
  const urgencyOrder = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3 };
  return suggestions.sort((a, b) => urgencyOrder[a.urgency] - urgencyOrder[b.urgency]);
}
async function analyzeCostOptimization(organizationId) {
  const optimizations = [];
  const thirtyDaysAgo = new Date;
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
  const orders = await db4.purchaseOrder.findMany({
    where: {
      location: { organizationId },
      status: "DELIVERED",
      createdAt: { gte: thirtyDaysAgo }
    },
    include: {
      items: {
        include: {
          product: { select: { name: true, category: true } }
        }
      },
      supplier: { select: { name: true } }
    }
  });
  const spendingByCategory = {};
  const spendingBySupplier = {};
  for (const order of orders) {
    spendingBySupplier[order.supplier.name] = (spendingBySupplier[order.supplier.name] || 0) + (order.totalAmount || 0);
    for (const item of order.items) {
      const category = item.product.category || "Uncategorized";
      spendingByCategory[category] = (spendingByCategory[category] || 0) + (item.unitPrice || 0) * item.quantity;
    }
  }
  const supplierCount = Object.keys(spendingBySupplier).length;
  if (supplierCount > 5) {
    optimizations.push({
      category: "Supplier Consolidation",
      potentialSavings: Math.round(Object.values(spendingBySupplier).reduce((a, b) => a + b, 0) * 0.05),
      recommendation: "Consider consolidating suppliers to negotiate better rates"
    });
  }
  const topCategories = Object.entries(spendingByCategory).sort((a, b) => b[1] - a[1]).slice(0, 3);
  for (const [category, amount] of topCategories) {
    optimizations.push({
      category: category === "Uncategorized" ? "General" : category,
      potentialSavings: Math.round(amount * 0.03),
      recommendation: `Review pricing for ${category} items - potential for better rates`
    });
  }
  return optimizations.sort((a, b) => b.potentialSavings - a.potentialSavings);
}
async function generateAISummary(organizationId) {
  const locations = await db4.location.count({
    where: { organizationId }
  });
  const products = await db4.product.count({
    where: { organizationId, isActive: true }
  });
  const stockLevels = await db4.stockLevel.findMany({
    where: { product: { organizationId } },
    include: { product: { select: { name: true } } }
  });
  let ok2 = 0, low = 0, critical = 0, out = 0;
  for (const sl of stockLevels) {
    const daysRemaining = sl.dailyUsage > 0 ? sl.onHand / sl.dailyUsage : 999;
    if (daysRemaining > 7)
      ok2++;
    else if (daysRemaining > 3)
      low++;
    else if (daysRemaining > 0)
      critical++;
    else
      out++;
  }
  const alerts = await db4.alert.count({
    where: {
      organizationId,
      isRead: false,
      isDismissed: false
    }
  });
  const sevenDaysAgo = new Date;
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  const recentWaste = await db4.wasteEntry.count({
    where: {
      location: { organizationId },
      createdAt: { gte: sevenDaysAgo }
    }
  });
  const headline = out > 0 ? `${out} item${out > 1 ? "s" : ""} need${out === 1 ? "s" : ""} immediate attention` : low > 0 ? `${low + critical} item${low + critical > 1 ? "s" : ""} running low` : "Inventory is in good shape";
  const summary = out > 0 ? `You have ${out} item${out > 1 ? "s" : ""} completely out of stock and ${critical} at critical levels. Reorder immediately to avoid service disruption.` : low + critical > 0 ? `${low} items are running low and ${critical} are at critical levels. Consider reordering soon.` : `All ${ok2} items have healthy stock levels. Great inventory management!`;
  const keyMetrics = [
    { label: "Products Tracked", value: products.toString() },
    { label: "Locations", value: locations.toString() },
    {
      label: "Stock Status",
      value: `${ok2} OK, ${low} Low, ${critical} Critical`
    },
    { label: "Active Alerts", value: alerts.toString(), change: alerts > 0 ? "action" : "good" },
    { label: "Waste This Week", value: recentWaste.toString(), change: recentWaste > 5 ? "warning" : "good" }
  ];
  const alertList = [];
  if (out > 0)
    alertList.push(`${out} items completely out of stock`);
  if (critical > 0)
    alertList.push(`${critical} items at critical levels`);
  if (recentWaste > 10)
    alertList.push(`High waste: ${recentWaste} items wasted this week`);
  const recommendations = [];
  if (out > 0) {
    recommendations.push("Urgent: Reorder out-of-stock items immediately");
  }
  if (low > 5) {
    recommendations.push("Consider bulk reorder for low-stock items");
  }
  if (recentWaste > 5) {
    recommendations.push("Review waste patterns to reduce spoilage");
  }
  if (recommendations.length === 0) {
    recommendations.push("Continue monitoring inventory levels");
    recommendations.push("Set up automated reorder rules for efficiency");
  }
  return {
    headline,
    summary,
    keyMetrics,
    alerts: alertList,
    recommendations
  };
}
