var app3 = new Hono2;
console.log("\uD83D\uDD27 Initializing Hono application for Vercel...");
app3.use("*", logger());
app3.use("/*", cors({
  origin: (origin) => origin || "*",
  credentials: true,
  allowHeaders: ["Content-Type", "Authorization", "expo-origin"],
  allowMethods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"]
}));
app3.use("*", async (c, next) => {
  const session = await auth.api.getSession({ headers: c.req.raw.headers });
  c.set("user", session?.user ?? null);
  c.set("session", session?.session ?? null);
  return next();
});
app3.on(["GET", "POST"], "/api/auth/*", (c) => {
  const request = c.req.raw;
  const expoOrigin = request.headers.get("expo-origin");
  if (!request.headers.get("origin") && expoOrigin) {
    const headers = new Headers(request.headers);
    headers.set("origin", expoOrigin);
    const modifiedRequest = new Request(request, { headers });
    return auth.handler(modifiedRequest);
  }
  return auth.handler(request);
});
